use crate::{storage::Database,windows_inventory::run_request};
use serde_json::{json,Value};use rusqlite::params;
fn query(request:Value)->Result<Value,String>{let script=format!("{}\n{}",include_str!("../scripts/task-common.ps1"),include_str!("../scripts/task-operation.ps1"));let data=run_request(&script,&request)?;data.as_array().and_then(|v|v.first()).cloned().ok_or("A tarefa não devolveu informação".into())}
pub fn inspect(path:&str)->Result<Value,String>{if !path.starts_with('\\')||path.len()>512||path.contains('\0'){return Err("Caminho inválido".into())}query(json!({"mode":"inspect","path":path}))}
pub fn disable(db:&Database,path:&str,expected_fingerprint:&str)->Result<Value,String>{let old=inspect(path)?;if old["CanDisable"]!=true{return Err(old["Reason"].as_str().unwrap_or("Tarefa não suportada").into())}if old["Fingerprint"]!=expected_fingerprint{return Err("A definição foi alterada".into())}if old["Enabled"]==false{return Ok(json!({"status":"unchanged"}))}let new=json!({"path":path,"enabled":false,"fingerprint":expected_fingerprint});let conn=db.0.lock().map_err(|e|e.to_string())?;conn.execute("INSERT INTO changes(optimization_id,previous_value,new_value,status,category) VALUES('tasks.optional',?1,?2,'pending','Tarefas')",params![old.to_string(),new.to_string()]).map_err(|e|e.to_string())?;let id=conn.last_insert_rowid();drop(conn);let result=query(json!({"mode":"write","path":path,"expected":true,"enabled":false,"fingerprint":expected_fingerprint}));db.0.lock().map_err(|e|e.to_string())?.execute("UPDATE changes SET status=?1,error=?2 WHERE id=?3",params![if result.is_ok(){"applied"}else{"failed"},result.as_ref().err(),id]).map_err(|e|e.to_string())?;db.log("task.disable",&json!({"id":id,"path":path,"success":result.is_ok()}).to_string())?;result?;Ok(json!({"id":id,"verified":true}))}
pub fn restore(db:&Database,id:i64)->Result<Value,String>{let conn=db.0.lock().map_err(|e|e.to_string())?;let(old,status):(String,String)=conn.query_row("SELECT previous_value,status FROM changes WHERE id=?1 AND optimization_id='tasks.optional'",[id],|r|Ok((r.get(0)?,r.get(1)?))).map_err(|e|e.to_string())?;drop(conn);if status=="restored"{return Ok(json!({"status":"restored"}))}let old:Value=serde_json::from_str(&old).map_err(|e|e.to_string())?;let path=old["Path"].as_str().ok_or("Backup sem caminho")?;let current=inspect(path)?;if current["Fingerprint"]!=old["Fingerprint"]{return Err("A definição da tarefa mudou; nada foi sobrescrito".into())}if current["Enabled"]!=old["Enabled"]{query(json!({"mode":"write","path":path,"expected":current["Enabled"],"enabled":old["Enabled"],"fingerprint":old["Fingerprint"]}))?;}db.0.lock().map_err(|e|e.to_string())?.execute("UPDATE changes SET status='restored',error=NULL WHERE id=?1",[id]).map_err(|e|e.to_string())?;db.log("task.restore",&id.to_string())?;Ok(json!({"status":"restored","verified":true}))}
